using System;
using System.Collections.Generic;
using System.Linq;
using Betta.Interfaces;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    /// <summary>
    /// One four-sided facade panel cut from a surface. Travels between components as a single
    /// "Panel" value (opaque), so corners, outline and metrics stay together.
    /// </summary>
    public sealed class Panel : IBettaValue
    {
        public Panel(Point3d a, Point3d b, Point3d c, Point3d d, int index)
        {
            Corners = new[] { a, b, c, d };
            Index = index;
            Outline = new PolylineCurve(new[] { a, b, c, d, a });
            Area = TriangleArea(a, b, c) + TriangleArea(a, c, d);
            Deviation = PlanarityDeviation(a, b, c, d);
            Center = new Point3d((a.X + b.X + c.X + d.X) / 4, (a.Y + b.Y + c.Y + d.Y) / 4, (a.Z + b.Z + c.Z + d.Z) / 4);
        }

        /// <summary>The four corners, in order around the panel.</summary>
        public IReadOnlyList<Point3d> Corners { get; }

        /// <summary>Closed outline through the four corners.</summary>
        public Curve Outline { get; }

        /// <summary>Area of the two triangles (0,1,2) and (0,2,3).</summary>
        public double Area { get; }

        /// <summary>Distance from the fourth corner to the plane through the first three.</summary>
        public double Deviation { get; }

        public Point3d Center { get; }

        /// <summary>Index in the panelization grid.</summary>
        public int Index { get; }

        /// <summary>Edge length i, from corner i to corner i+1 (wrapping).</summary>
        public double EdgeLength(int i) => Corners[i % 4].DistanceTo(Corners[(i + 1) % 4]);

        public double[] SortedEdgeLengths() =>
            Enumerable.Range(0, 4).Select(EdgeLength).OrderBy(x => x).ToArray();

        public double[] SortedDiagonalLengths() =>
            new[] { Corners[0].DistanceTo(Corners[2]), Corners[1].DistanceTo(Corners[3]) }.OrderBy(x => x).ToArray();

        /// <summary>Fabrication rectangle width: mean of the first and third edges.</summary>
        public double RectWidth => (EdgeLength(0) + EdgeLength(2)) / 2;

        /// <summary>Fabrication rectangle height: mean of the second and fourth edges.</summary>
        public double RectHeight => (EdgeLength(1) + EdgeLength(3)) / 2;

        public Curve DuplicateOutline() => Outline.DuplicateCurve();

        public override string ToString() => $"Panel {Index} (area {Area:0.##}, dev {Deviation:0.###})";

        private static double TriangleArea(Point3d a, Point3d b, Point3d c) =>
            Vector3d.CrossProduct(b - a, c - a).Length / 2;

        private static double PlanarityDeviation(Point3d a, Point3d b, Point3d c, Point3d d)
        {
            var normal = Vector3d.CrossProduct(b - a, c - a);
            if (!normal.Unitize()) return 0; // first three corners collinear: any plane through them fits d
            return Math.Abs((d - a) * normal);
        }
    }
}

