using System;
using System.Collections.Generic;
using System.Linq;
using Betta.Attributes;
using Betta.Interfaces;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    [GrasshopperCollection("Facade", "Panels")]
    public interface IFacadePanels : IBettaCollection
    {
        [GrasshopperMethod("Panelize Surface", "Divides a surface's domain evenly into four-sided panels")]
        (List<Panel> Panels, List<Curve> Outlines) PanelizeSurface(
            [GrasshopperParameter("Surface")] Surface surface,
            [GrasshopperParameter("U Count", DefaultValue = 10)] int uCount,
            [GrasshopperParameter("V Count", DefaultValue = 6)] int vCount);

        [GrasshopperMethod("Panel Info", "Corners, outline, area, center and grid index of a panel")]
        (List<Point3d> Corners, Curve Outline, double Area, Point3d Center, int Index) PanelInfo(
            [GrasshopperParameter("Panel")] Panel panel);
    }

    public class FacadePanels : IFacadePanels
    {
        public (List<Panel> Panels, List<Curve> Outlines) PanelizeSurface(Surface surface, int uCount, int vCount)
        {
            if (surface == null) throw new ArgumentNullException(nameof(surface), "Surface is required");
            if (uCount < 1) throw new ArgumentOutOfRangeException(nameof(uCount), "U Count must be at least 1");
            if (vCount < 1) throw new ArgumentOutOfRangeException(nameof(vCount), "V Count must be at least 1");

            Interval du = surface.Domain(0), dv = surface.Domain(1);
            var grid = new Point3d[uCount + 1, vCount + 1];
            for (int i = 0; i <= uCount; i++)
                for (int j = 0; j <= vCount; j++)
                    grid[i, j] = surface.PointAt(du.ParameterAt((double)i / uCount), dv.ParameterAt((double)j / vCount));

            var panels = new List<Panel>(uCount * vCount);
            for (int i = 0; i < uCount; i++)
                for (int j = 0; j < vCount; j++)
                    panels.Add(new Panel(grid[i, j], grid[i + 1, j], grid[i + 1, j + 1], grid[i, j + 1], i * vCount + j));

            return (panels, panels.Select(p => p.DuplicateOutline()).ToList());
        }

        public (List<Point3d> Corners, Curve Outline, double Area, Point3d Center, int Index) PanelInfo(Panel panel)
        {
            if (panel == null) throw new ArgumentNullException(nameof(panel), "Panel is required");
            return (panel.Corners.ToList(), panel.DuplicateOutline(), panel.Area, panel.Center, panel.Index);
        }
    }
}

