                    // Prefer the part as-is; turn it 90 degrees only when it fits turned and not as-is.
                    if (FitsShelf(w, h)) { }
                    else if (FitsShelf(h, w)) (w, h) = (h, w);
                    else if (FitsNewShelf(w, h) || FitsNewShelf(h, w))
