                  .Append(p.RectWidth.ToString("0.###", inv)).Append(',')
                  .Append(p.RectHeight.ToString("0.###", inv)).Append(',')
                  .Append(p.Area.ToString("0.###", inv)).Append(',')
                  .Append(p.Deviation.ToString("0.####", inv)).Append('\n');
            }
            string csv = sb.ToString();

